package sshterm

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
)

// DirKeys loads the keys generated by POST /accounts/ssh-keys, stored as <Dir>/<user>.key.
type DirKeys struct {
	Dir string
}

func (k DirKeys) Load(user string) ([]byte, error) {
	b, err := os.ReadFile(filepath.Join(k.Dir, user+".key"))
	if errors.Is(err, fs.ErrNotExist) {
		return nil, ErrNoKey
	}
	if err != nil {
		return nil, fmt.Errorf("read key: %w", err)
	}
	return b, nil
}
